window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bc33f74a8481d8e8"]={"versions": [{"id": "FIG-bc33f74a8481d8e8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptuelles Metamodellierungs- und Vergleichsdiagramm im Kontext der AUTOSAR Adaptive Platform Machine Configuration (TPS MachineConfiguration). Das Schaubild stellt eine Gegenüberstellung zweier Modellierungsebenen dar, getrennt durch eine vertikal gestrichelte Trennlinie: Auf der linken Seite befindet sich die Metamodellebene M2 (Klassenhierarchie mit Vererbung), auf der rechten Seite die Zielkonfigurationsebene M1 (Instanziierung bzw. Definitionsseite unter Nutzung von Choice-Containern zur Emulation von Polymorphie/Vererbung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei modelltheoretische Hälften:</p>\n<ul class=\"fig-list\"><li><strong>M2-Ebene (links):</strong>\n<ul class=\"fig-list\"><li>Klasse <code>X</code> aggregiert per Komposition (gefüllte Raute) die Klasse <code>A</code>.\n</li><li>Die Klassen <code>B</code> und <code>C</code> erben von der Basisklasse <code>A</code> (Vererbungspfeile mit geschlossener, nicht ausgefüllter Dreiecksspitze).\n</li></ul>\n</li><li><strong>M1-Ebene (rechts):</strong>\n<ul class=\"fig-list\"><li>Instanz bzw. Element <code>X: ApmcParamConfContainerDef</code>.\n</li><li>Element <code>X: ApmcChoiceContainerDef</code>, aggregiert durch <code>X: ApmcParamConfContainerDef</code> über die Kompositionsrolle <code>container</code>.\n</li><li>Elemente <code>B: ApmcParamConfContainerDef</code> und <code>C: ApmcParamConfContainerDef</code>, die beide durch <code>X: ApmcChoiceContainerDef</code> jeweils über die Kompositionsrolle <code>choice</code> aggregiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Abbildungsdiagramm ohne dynamische Ausführungsreihenfolge oder Laufzeitsequenz. Es visualisiert das Mapping-Prinzip zur Erzeugung konfigurierbarer Spezialisierungen: Eine Vererbungsbeziehung auf M2-Ebene (wo <code>B</code> und <code>C</code> von <code>A</code> ableiten und als <code>A</code> in <code>X</code> eingebettet werden können) wird im M1-Definitionsmodell durch einen übergeordneten <code>ApmcChoiceContainerDef</code> realisiert, der die konkreten Varianten <code>B</code> und <code>C</code> als Auswahloptionen (<code>choice</code>) zur Verfügung stellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient dem Verständnis und der normativen Umsetzung der Choice-Container-Semantik gemäß <code>[AP_TPS_APMC_01006]</code>. Da die Zielkonfiguration auf Instanzebene keine native objektorientierte M2-Vererbung abbildet, müssen Konfigurationswerkzeuge und Modellierer Polymorphie über <code>ApmcChoiceContainerDef</code> mit Rollennamen <code>choice</code> abbilden. Dies stellt sicher, dass an Stelle der abstrakten Definition genau eine der spezialisierten Containerdefinitionen ausgewählt und validiert werden kann.</p>"}, {"id": "FIG-3d5f8f58ff9e5cd4", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptuelles Metamodellierungs- und Vergleichsdiagramm im Kontext der AUTOSAR Adaptive Platform Machine Configuration (TPS MachineConfiguration). Das Schaubild stellt eine Gegenüberstellung zweier Modellierungsebenen dar, getrennt durch eine vertikal gestrichelte Trennlinie: Auf der linken Seite befindet sich die Metamodellebene M2 (Klassenhierarchie mit Vererbung), auf der rechten Seite die Zielkonfigurationsebene M1 (Instanziierung bzw. Definitionsseite unter Nutzung von Choice-Containern zur Emulation von Polymorphie/Vererbung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei modelltheoretische Hälften:</p>\n<ul class=\"fig-list\"><li><strong>M2-Ebene (links):</strong>\n<ul class=\"fig-list\"><li>Klasse <code>X</code> aggregiert per Komposition (gefüllte Raute) die Klasse <code>A</code>.\n</li><li>Die Klassen <code>B</code> und <code>C</code> erben von der Basisklasse <code>A</code> (Vererbungspfeile mit geschlossener, nicht ausgefüllter Dreiecksspitze).\n</li></ul>\n</li><li><strong>M1-Ebene (rechts):</strong>\n<ul class=\"fig-list\"><li>Instanz bzw. Element <code>X: ApmcParamConf-ContainerDef</code>.\n</li><li>Element <code>A: ApmcChoiceContainerDef</code>, aggregiert durch <code>X: ApmcParamConf-ContainerDef</code> über die Kompositionsrolle <code>container</code>.\n</li><li>Elemente <code>B: ApmcParamConf-ContainerDef</code> und <code>C: ApmcParamConf-ContainerDef</code>, die beide durch <code>A: ApmcChoiceContainerDef</code> jeweils über die Kompositionsrolle <code>choice</code> aggregiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Abbildungsdiagramm ohne dynamische Ausführungsreihenfolge oder Laufzeitsequenz. Es visualisiert das Mapping-Prinzip zur Erzeugung konfigurierbarer Spezialisierungen: Eine Vererbungsbeziehung auf M2-Ebene (wo <code>B</code> und <code>C</code> von <code>A</code> ableiten und als <code>A</code> in <code>X</code> eingebettet werden können) wird im M1-Definitionsmodell durch einen übergeordneten <code>ApmcChoiceContainerDef</code> realisiert, der die konkreten Varianten <code>B</code> und <code>C</code> als Auswahloptionen (<code>choice</code>) zur Verfügung stellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient dem Verständnis und der normativen Umsetzung der Choice-Container-Semantik gemäß <code>[AP_TPS_APMC_01006]</code>. Da die Zielkonfiguration auf Instanzebene keine native objektorientierte M2-Vererbung abbildet, müssen Konfigurationswerkzeuge und Modellierer Polymorphie über <code>ApmcChoiceContainerDef</code> mit Rollennamen <code>choice</code> abbilden. Dies stellt sicher, dass an Stelle der abstrakten Definition genau eine der spezialisierten Containerdefinitionen ausgewählt und validiert werden kann.</p>"}], "trans": [{"from": "FIG-bc33f74a8481d8e8", "to": "FIG-3d5f8f58ff9e5cd4", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>M1-Objekt <code>ApmcChoiceContainerDef</code>: Instanzbezeichner von <code>X: ApmcChoiceContainerDef</code> korrigiert zu <code>A: ApmcChoiceContainerDef</code> passend zum M2-Element <code>A</code>.\n</li><li>Typnamen in den M1-Klassenboxen (<code>X</code>, <code>B</code>, <code>C</code>): <code>ApmcParamConfContainerDef</code> typografisch mit Trennstrich umbrochen (<code>ApmcParamConf-ContainerDef</code>).\n</li><li>Typografisches Re-Rendering der M2- und M1-Beschriftungen an der Trennlinie.\n</li></ul>"}]};
